import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"常见错误及其修复","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/common-errors.md","filePath":"zh/troubleshooting/common-errors.md"}'),a={name:"zh/troubleshooting/common-errors.md"};function c(h,t,i,s,l,n){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="常见错误及其修复" tabindex="-1">常见错误及其修复 <a class="header-anchor" href="#常见错误及其修复" aria-label="Permalink to &quot;常见错误及其修复&quot;">​</a></h1><h2 id="构建" tabindex="-1">构建 <a class="header-anchor" href="#构建" aria-label="Permalink to &quot;构建&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td><code>grub-mkimage: cannot open ... unicode.pf2</code></td><td>字体在 <code>grub-common</code> 里</td><td>安装它 / 把 OC_TOOLS 指向包含 <code>usr/share/grub/unicode.pf2</code> 的目录树</td></tr><tr><td><code>src-zip: not a git checkout</code></td><td>没有 git 元数据</td><td>从克隆构建，或使用 <code>make dist</code></td></tr><tr><td><code>error: operand size mismatch for &#39;setc&#39;</code></td><td>新 GAS 上的修复前代码树</td><td>更新越过提交 fc4e5a5（u8 标志）</td></tr><tr><td>新 GCC 上的 packed-member 警告</td><td>修复前代码树</td><td>更新越过 fc4e5a5（packed 标签类型）</td></tr><tr><td><code>embed_grub: missing /usr/usr/lib/grub...</code></td><td>修复前脚本</td><td>更新越过 fc4e5a5（双布局探测）</td></tr></tbody></table><h2 id="启动" tabindex="-1">启动 <a class="header-anchor" href="#启动" aria-label="Permalink to &quot;启动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>含义</th><th>下一步</th></tr></thead><tbody><tr><td>没有 <code>multiboot2 handshake OK</code></td><td>OCBL 没有交出有效的 mbi</td><td>检查 ISO 启动的是否为正确条目（OCBL 菜单）；捕获串口</td></tr><tr><td>启动停在某个非 OK 行</td><td>该子系统失败</td><td>找到实现它的文件——读它的初始化错误路径</td></tr><tr><td>三重故障/复位循环</td><td>转储路径可用之前的早期异常</td><td><code>-d int,cpu_reset -D qemu.log</code> + 经 <code>-s -S</code> 接入的 gdb</td></tr><tr><td>启动菜单选错槽位</td><td>A/B 标志过期</td><td>从菜单强制另一个槽位，然后 <code>update rollback</code></td></tr></tbody></table><h2 id="运行期" tabindex="-1">运行期 <a class="header-anchor" href="#运行期" aria-label="Permalink to &quot;运行期&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>含义</th><th>下一步</th></tr></thead><tbody><tr><td><code>mount</code> 拒绝有效的 FAT32 卷</td><td>BPB 检查失败</td><td><code>fatstat &lt;dev&gt;</code> 显示解析出的 BPB；设备搞错了？</td></tr><tr><td>网卡沉默</td><td>驱动未绑定</td><td><code>lspci</code> + 家族命令（<code>e1000</code>…）</td></tr><tr><td>TCP 连上后停摆</td><td>校验和/重构回归</td><td><code>tcpstats</code>、<code>tcptest</code></td></tr><tr><td>U 盘缺失</td><td>USB MSC 未绑定</td><td><code>usb</code>、<code>usb_storage_test</code></td></tr><tr><td>干净卸载后 fsck 报 dirty</td><td>FSINFO/FAT 镜像回归</td><td>上报它——这一类就是 bug</td></tr></tbody></table><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><ul><li>SSH E2E 需要预置的主机密钥（<a href="./../dev/e2e-suites.html">../dev/e2e-suites.md</a> 中的 mtools 配方）。</li><li>HTTPS E2E 需要参考服务器可达。</li><li>回归套件需要 pexpect；SSH 套件需要 paramiko。</li></ul>',9)])])}const m=d(a,[["render",c]]);export{u as __pageData,m as default};
